def subtract(a, b):
    events = []
    for start, end in a:
        if start < end:
            events.append((start, 0, 1))   # type 0 = 'a' start
            events.append((end, 0, -1))    # type 0 = 'a' end
    for start, end in b:
        if start < end:
            events.append((start, 1, 1))   # type 1 = 'b' start
            events.append((end, 1, -1))    # type 1 = 'b' end

    if not events:
        return []

    xs = sorted(set(x for x, _, _ in events))

    # Build delta maps for a and b at each x
    a_delta = {x: 0 for x in xs}
    b_delta = {x: 0 for x in xs}
    for x, typ, d in events:
        if typ == 0:
            a_delta[x] += d
        else:
            b_delta[x] += d

    result = []
    a_count = 0
    b_count = 0
    cur_start = None

    for i in range(len(xs)):
        x = xs[i]
        a_count += a_delta[x]
        b_count += b_delta[x]

        covered = a_count > 0 and b_count == 0

        if i + 1 < len(xs):
            next_x = xs[i+1]
        else:
            next_x = None

        if covered and next_x is not None:
            if cur_start is None:
                cur_start = x
        else:
            if cur_start is not None:
                result.append([cur_start, x])
                cur_start = None

    return result

